package vn.rtr.aeris.shell24;
import android.app.Activity;import android.os.*;import android.content.*;import android.graphics.*;import android.hardware.input.InputManager;import android.media.MediaPlayer;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.security.*;import java.nio.file.Files;import java.nio.file.StandardCopyOption;import java.util.*;import java.util.concurrent.*;

/** Native preparation: local media, raw input observation, pure mock replay. No vehicle bridge. */
public final class ShellActivity extends Activity implements TextureView.SurfaceTextureListener,InputManager.InputDeviceListener {
 private final ShellState shell=new ShellState();private final ArrayDeque<String> raw=new ArrayDeque<>();private int rawDropped=0;private long lastRaw=-1;private boolean observeRaw=false,foreground=false,destroyed=false,busy=false;private volatile long ioGeneration=0;private byte[] pendingExport;private String message="Không có aircraft/radio. Input và video thực chưa kiểm trên HeraHub.",previous="Chưa có snapshot lịch sử",selectedName="Chưa chọn clip";private File selectedFile;private String selectedHash;private String selectedOrigin;
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(1),new ThreadPoolExecutor.AbortPolicy());private TextView status,details,title;private LinearLayout root,actions;private TextureView texture;private MediaPlayer player;private Surface surface;private InputManager inputManager;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private long now(){return SystemClock.elapsedRealtime();}
 @Override public void onCreate(Bundle b){super.onCreate(b);inputManager=(InputManager)getSystemService(INPUT_SERVICE);inputManager.registerInputDeviceListener(this,new Handler(Looper.getMainLooper()));readHistory();layout();}
 private TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(dp(8),dp(6),dp(8),dp(6));return v;}
 private Button button(String label,Runnable r){Button b=new Button(this);b.setText(label);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff22272e));b.setMinHeight(dp(48));b.setContentDescription(label);b.setOnClickListener(v->r.run());return b;}
 private void row(LinearLayout parent,String[] labels,Runnable[] jobs){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);for(int n=0;n<labels.length;n++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(64),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(button(labels[n],jobs[n]),p);}parent.addView(row);}
 private void layout(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.BLACK);root.setPadding(dp(12),dp(8),dp(12),dp(8));setContentView(root);title=text("AERIS  /  Native preparation",22,Color.WHITE);root.addView(title);root.addView(text("Prototype offline • không kết nối máy bay • build "+BuildInfo.SOURCE_ID.substring(0,12),12,0xffc7ced6));
 row(root,new String[]{"Plan","Fly","Review"},new Runnable[]{()->navigate("Plan"),()->navigate("Fly"),()->navigate("Review")});status=text("",14,0xffefcd36);root.addView(status);
 FrameLayout stage=new FrameLayout(this);stage.setBackgroundColor(0xff15181c);stage.addView(new PlanSurface(this),new FrameLayout.LayoutParams(-1,-1));texture=new TextureView(this);texture.setOpaque(false);texture.setAlpha(0f);texture.setSurfaceTextureListener(this);stage.addView(texture,new FrameLayout.LayoutParams(-1,-1));root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));
 actions=new LinearLayout(this);actions.setOrientation(LinearLayout.VERTICAL);row(actions,new String[]{"Clip tổng hợp","Chọn clip local","Phát / dừng"},new Runnable[]{this::chooseFixture,this::chooseDocument,this::togglePlay});row(actions,new String[]{"Replay input","Quan sát raw input","Xuất review"},new Runnable[]{this::replayInput,()->{observeRaw=!observeRaw;message=observeRaw?"Raw input observation-only; không gán channel/flight":"Dừng quan sát raw input";refresh();},this::exportReview});root.addView(actions);
 ScrollView scroll=new ScrollView(this);details=text("",13,0xffc7ced6);scroll.addView(details);root.addView(scroll,new LinearLayout.LayoutParams(-1,dp(104)));refresh();}
 private void navigate(String p){stopPlayer("WORKSPACE_CHANGED");shell.navigate(p);message=p.equals("Plan")?"Vùng khảo sát minh họa; không có bản đồ/mission thực":p.equals("Fly")?"Chọn clip local hoặc xem replay input":"Review chứa provenance; không chứng minh capture/flight";historyAsync();refresh();}
 private void refresh(){if(destroyed||status==null)return;title.setText("AERIS  /  "+shell.workspace);status.setText(message);details.setText("Video: "+selectedName+"\n"+shell.video.state+" • frame age chưa biết • media thực chưa kiểm\n"+"Input: "+shell.input.reason()+" • raw "+raw.size()+" / dropped "+rawDropped+"\n"+previous);}
 private void error(String m){message=m;refresh();}
 private void chooseFixture(){if(busy){error("I/O đang bận; chọn lại khi hoàn tất");return;}stopPlayer("SOURCE_CHANGE");final long job=++ioGeneration;busy=true;submit(()->{File tmp=new File(getFilesDir(),"fixture.pending");try(InputStream in=getAssets().open("synthetic.webm")){String hash=copy(in,tmp);if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");File dst=publishLocal(tmp,hash);runOnUiThread(()->{busy=false;if(!destroyed&&job==ioGeneration&&foreground)select(dst,hash,"SYNTHETIC_FIXTURE","Clip tổng hợp • VP8 • không ảnh camera");});}catch(Exception e){tmp.delete();runOnUiThread(()->{busy=false;error("Không chọn được clip tổng hợp: "+e.getClass().getSimpleName());});}});}
 private void chooseDocument(){if(busy){error("I/O đang bận");return;}stopPlayer("DOCUMENT_PICKER");observeRaw=false;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_LOCAL_ONLY,true);try{startActivityForResult(i,1);}catch(Exception e){error("File picker không khả dụng");}}
 private void select(File f,String hash,String origin,String label){stopPlayer("SOURCE_CHANGE");selectedFile=f;selectedHash=hash;selectedOrigin=origin;selectedName=label;shell.video.select(origin,hash,f.length(),now());message="Clip được hash; bấm Phát để kiểm playback local";historyAsync();refresh();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){error("Không chọn file; không tự tiếp tục playback/input");return;}Uri uri=data.getData();if(!"content".equals(uri.getScheme())){error("Chỉ nhận document content URI đã chọn");return;}if(busy){error("I/O đang bận");return;}final long job=++ioGeneration;busy=true;
 if(request==1){submit(()->{File tmp=new File(getFilesDir(),"import.pending");try(InputStream in=getContentResolver().openInputStream(uri)){String hash=copy(in,tmp);File dst=publishLocal(tmp,hash);runOnUiThread(()->{busy=false;if(!destroyed&&job==ioGeneration&&foreground)select(dst,hash,"IMPORTED_LOCAL_UNATTESTED","File người dùng • nguồn chưa xác thực");});}catch(Exception e){tmp.delete();runOnUiThread(()->{busy=false;error("Import bị từ chối: "+e.getClass().getSimpleName());});}});}
 else if(request==2){final byte[] bytes=pendingExport;pendingExport=null;if(bytes==null){busy=false;error("Snapshot export mất sau recreation; chuẩn bị lại");return;}submit(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(bytes.length>262144||out==null)throw new IOException("Export size/provider");out.write(bytes);out.flush();runOnUiThread(()->{busy=false;error("Đã xuất review lịch sử, không chứng minh thiết bị/flight");});}catch(Exception e){runOnUiThread(()->{busy=false;error("Export có thể chưa đủ; không dùng file lỗi làm bằng chứng");});}});}else busy=false;}
 private String copy(InputStream in,File tmp)throws Exception{long stored=0;for(File f:getFilesDir().listFiles()){if(f.getName().endsWith(".webm"))stored+=f.length();}if(stored>VideoModel.MAX_BYTES||getFilesDir().getUsableSpace()<VideoModel.MAX_BYTES+16L*1024*1024)throw new IOException("Local quota/reserve");if(in==null)throw new IOException("No input");MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0,start=now();try(FileOutputStream out=new FileOutputStream(tmp)){byte[] chunk=new byte[65536];int n;while((n=in.read(chunk))!=-1){if(Thread.currentThread().isInterrupted()||now()-start>30000)throw new IOException("Copy cancelled/deadline");total+=n;if(total>VideoModel.MAX_BYTES)throw new IOException("64MiB cap");out.write(chunk,0,n);digest.update(chunk,0,n);}if(total==0)throw new IOException("Empty");out.getFD().sync();}return hex(digest.digest());}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(java.util.Locale.ROOT,"%02x",x&255));return s.toString();}
 private File publishLocal(File tmp,String hash)throws Exception{File dst=new File(getFilesDir(),hash+".webm");if(dst.exists()){try(InputStream in=new FileInputStream(dst)){MessageDigest d=MessageDigest.getInstance("SHA-256");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);if(!hex(d.digest()).equals(hash))throw new IOException("Stored hash mismatch");}tmp.delete();}else Files.move(tmp.toPath(),dst.toPath(),StandardCopyOption.ATOMIC_MOVE);return dst;}
 private void atomic(File tmp,File dst)throws IOException{Files.move(tmp.toPath(),dst.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 private void submit(Runnable task){try{worker.execute(task);}catch(RejectedExecutionException e){busy=false;error("Worker đang bận; không xếp thêm I/O");}}
 private void togglePlay(){if(player!=null){stopPlayer("OPERATOR_STOPPED");message="Đã dừng local playback";refresh();return;}if(selectedFile==null||!texture.isAvailable()||!shell.focused||busy){error("Chọn clip và giữ focus trước khi phát");return;}
 try{surface=new Surface(texture.getSurfaceTexture());final MediaPlayer mp=new MediaPlayer();player=mp;final long generation=shell.video.prepare(now());mp.setSurface(surface);mp.setVolume(0,0);mp.setLooping(false);mp.setDataSource(selectedFile.getAbsolutePath());mp.setOnPreparedListener(v->{if(player!=mp||generation!=shell.video.generation)return;if(!shell.focused||!shell.video.prepared(generation,v.getVideoWidth(),v.getVideoHeight(),v.getDuration(),now())){stopPlayer("UNSUPPORTED_LOCAL_VIDEO");error("Clip cần kích thước <=1920×1080 và thời lượng <=120s");return;}if(shell.video.play(generation,now())){texture.setAlpha(1f);v.start();message="Local playback • chưa đo frame age/latency native";refresh();}});
 mp.setOnInfoListener((v,what,extra)->{if(player==mp&&generation==shell.video.generation&&what==MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START){shell.video.rendered(generation,now());refresh();}return false;});mp.setOnCompletionListener(v->{if(player==mp&&generation==shell.video.generation){shell.video.ended(generation,now());releasePlayer();message="Clip đã kết thúc; không tự loop";refresh();}});mp.setOnErrorListener((v,a,b)->{if(player==mp&&generation==shell.video.generation){stopPlayer("DECODE_ERROR");error("Decoder từ chối clip; cần kiểm trên đúng Android build");}return true;});mp.prepareAsync();message="Chuẩn bị decoder local";refresh();}catch(Exception e){stopPlayer("PLAYER_ERROR");error("Không mở được local player");}}
 private void releasePlayer(){if(texture!=null)texture.setAlpha(0f);MediaPlayer old=player;player=null;if(old!=null){old.setOnPreparedListener(null);old.setOnInfoListener(null);old.setOnErrorListener(null);old.setOnCompletionListener(null);old.release();}if(surface!=null){surface.release();surface=null;}}
 private void stopPlayer(String reason){shell.video.stop(reason);releasePlayer();}
 private void replayInput(){stopPlayer("REPLAY_INSPECTION");try{JSONObject r=new JSONObject(Replay.run("focus"));message="Replay mock: mất focus hủy quyền; resume không cấp lại";details.setText(r.toString(2));status.setText(message);}catch(Exception e){error("Replay không khả dụng");}}
 private void trace(String s){if(raw.size()==128){raw.removeFirst();rawDropped++;}raw.addLast(s);refresh();}
 @Override public boolean onGenericMotionEvent(MotionEvent e){if(observeRaw&&shell.focused&&(e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK&&e.getAction()==MotionEvent.ACTION_MOVE){long t=e.getEventTime();if(t-lastRaw>=50){lastRaw=t;InputDevice d=e.getDevice();int n=0;StringBuilder s=new StringBuilder("RAW_ONLY t="+t+" device="+e.getDeviceId());if(d!=null)for(InputDevice.MotionRange range:d.getMotionRanges()){if(n++==16)break;s.append(" axis=").append(range.getAxis()).append(" value=").append(e.getAxisValue(range.getAxis()));}trace(s.toString());}return true;}return super.onGenericMotionEvent(e);}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(observeRaw&&shell.focused&&(e.getSource()&InputDevice.SOURCE_GAMEPAD)==InputDevice.SOURCE_GAMEPAD){trace("RAW_ONLY device="+e.getDeviceId()+" key="+e.getKeyCode()+" action="+e.getAction()+" repeat="+e.getRepeatCount());return true;}return super.dispatchKeyEvent(e);}
 @Override public void onInputDeviceAdded(int id){trace("RAW_DEVICE_ADDED "+id);}@Override public void onInputDeviceChanged(int id){observeRaw=false;shell.input.detach(now());trace("RAW_DEVICE_CHANGED "+id);}@Override public void onInputDeviceRemoved(int id){observeRaw=false;shell.input.detach(now());trace("RAW_DEVICE_REMOVED "+id);}
 private String report(){try{JSONObject o=new JSONObject(shell.report());o.put("buildId",BuildInfo.SOURCE_ID);o.put("capturedElapsedMs",now());o.put("capturedUTCMillis",System.currentTimeMillis());o.put("rawDeviceIdsScope","SESSION_LOCAL_ANDROID_INDICES");o.put("producer","ANDROID_COMPILED_PREPARATION_NOT_ATTESTED");o.put("rawInputScope","OBSERVATION_ONLY_NOT_CALIBRATED");o.put("rawInputDropped",rawDropped);JSONArray rows=new JSONArray();for(String s:raw)rows.put(s);o.put("rawInput",rows);return o.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 private void exportReview(){pendingExport=report().getBytes(java.nio.charset.StandardCharsets.UTF_8);stopPlayer("EXPORT_PICKER");observeRaw=false;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"aeris-native24-review.json");try{startActivityForResult(i,2);}catch(Exception e){error("Export picker không khả dụng");}}
 private void readHistory(){File f=new File(getFilesDir(),"history.json");if(f.exists())try{if(f.length()>8192)throw new IOException("History cap");JSONObject o=new JSONObject(new String(Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8));if(!o.optString("format").equals("aeris-native24-history")||o.optInt("version")!=1||o.optBoolean("authorityRestorable",true))throw new IOException("History schema");previous="Snapshot lịch sử: "+o.optString("workspace")+" • session "+o.optString("historicalSession")+" • không restore input/video";}catch(Exception e){previous="Snapshot lịch sử lỗi; giữ file, không restore";}}
 private void historyAsync(){final byte[] b=shell.checkpoint().getBytes(java.nio.charset.StandardCharsets.UTF_8);try{worker.execute(()->{File tmp=new File(getFilesDir(),"history.pending");try(FileOutputStream out=new FileOutputStream(tmp)){if(b.length>8192)throw new IOException("History cap");out.write(b);out.getFD().sync();atomic(tmp,new File(getFilesDir(),"history.json"));}catch(Exception e){runOnUiThread(()->error("Snapshot chưa lưu; giữ bản lịch sử trước"));}});}catch(RejectedExecutionException e){error("Snapshot chưa xếp được vì worker bận");}}
 @Override protected void onResume(){super.onResume();foreground=true;message="Session hiện tại chưa có quyền input/playback; thao tác lại rõ ràng";refresh();}
 @Override public void onWindowFocusChanged(boolean f){super.onWindowFocusChanged(f);shell.focus(f,now());if(!f){observeRaw=false;stopPlayer("FOCUS_LOST");}refresh();}
 @Override protected void onPause(){foreground=false;ioGeneration++;observeRaw=false;shell.focus(false,now());stopPlayer("PAUSED");historyAsync();super.onPause();}
 @Override protected void onDestroy(){destroyed=true;ioGeneration++;observeRaw=false;releasePlayer();inputManager.unregisterInputDeviceListener(this);worker.shutdownNow();super.onDestroy();}
 @Override public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){}@Override public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){}@Override public boolean onSurfaceTextureDestroyed(SurfaceTexture t){stopPlayer("SURFACE_LOST");refresh();return true;}@Override public void onSurfaceTextureUpdated(SurfaceTexture t){}
 private final class PlanSurface extends View {private final Paint p=new Paint(3);PlanSurface(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);p.setColor(0xff353b43);p.setStrokeWidth(dp(1));int w=getWidth(),h=getHeight();for(int x=0;x<w;x+=dp(60))c.drawLine(x,0,x,h,p);for(int y=0;y<h;y+=dp(60))c.drawLine(0,y,w,y,p);p.setColor(0xffc7ced6);p.setStyle(Paint.Style.STROKE);Path path=new Path();path.moveTo(w*.18f,h*.28f);path.lineTo(w*.74f,h*.2f);path.lineTo(w*.86f,h*.73f);path.lineTo(w*.28f,h*.8f);path.close();c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setTextSize(dp(16));c.drawText("Vùng minh họa • không geodata/mission thực",dp(20),h-dp(22),p);}}
}
